"""Contract tests generated by API Shakedown. The cases live in contract_cases.json.

Configuration: see shakedown_support.py. Requires pytest, httpx, openapi-schema-validator.
"""

from collections.abc import Iterator
from typing import Any

import httpx
import pytest
from shakedown_support import (
    TIMEOUT,
    build_request,
    load_cases,
    schema_problems,
    status_matches,
    target_url,
)

DATA = load_cases(__file__, "contract_cases.json")


@pytest.fixture(scope="module")
def client() -> Iterator[httpx.Client]:
    with httpx.Client(base_url=target_url(DATA), timeout=TIMEOUT) as session:
        yield session


@pytest.mark.parametrize("case", DATA["cases"], ids=[c["id"] for c in DATA["cases"]])
def test_contract(client: httpx.Client, case: dict[str, Any]) -> None:
    request = build_request(case, DATA["status_header"], select=case["expected_status"])
    response = client.request(**request)
    where = f"{case['method'].upper()} {response.request.url}"

    assert status_matches(response.status_code, case["expected_status"], case["other_statuses"]), (
        f"{where}: expected status {case['expected_status']}, got {response.status_code}. "
        f"Body: {response.text[:500]}"
    )

    expected_type = case["response_content_type"]
    if expected_type and response.content:
        actual_type = response.headers.get("content-type", "").split(";")[0].strip()
        assert actual_type == expected_type.split(";")[0].strip(), (
            f"{where}: expected Content-Type {expected_type}, got {actual_type or 'none'}."
        )

    schema = case["response_schema"]
    if schema is not None and expected_type and "json" in expected_type and response.content:
        problems = schema_problems(schema, response.json(), DATA["openapi_version"])
        assert not problems, f"{where}: response violates the schema:\n" + "\n".join(problems)
